import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { SegmentedButtonProps } from "./segmented-button.types";
import { SegmentedButtonClasses, StyledSegmentedButton } from "./segmented-button.styles";
import { useSegmentedButton } from "./hooks/use-segmented-button";

const SegmentedButton = forwardRef(
  (
    {
      className,
      variant = "default",
      children,
      behavior = "button",
      selected: controlledSelected,
      defaultSelected,
      onValueChange,
      disabled = false,
      size,
      required = false,
      ...props
    }: SegmentedButtonProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(
      SegmentedButtonClasses.root,
      {
        [SegmentedButtonClasses.sm]: size === "sm",
      },
      className,
    );

    const { role, handleKeyDown, renderChildren } = useSegmentedButton({
      disabled,
      behavior,
      selected: controlledSelected,
      defaultSelected,
      onValueChange,
      children,
      variant,
      size,
      required,
    });

    return (
      <StyledSegmentedButton
        ref={ref}
        aria-orientation={behavior === "radio" ? "horizontal" : undefined}
        className={rootClasses}
        currentTheme={theme}
        role={role}
        variant={variant}
        onKeyDown={handleKeyDown}
        {...props}
      >
        {renderChildren()}
      </StyledSegmentedButton>
    );
  },
);

SegmentedButton.displayName = "SegmentedButton";

export default SegmentedButton;
